raw_text:
{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "ཞེས་གསུངས་པའི་ཕྱིར་ཞེ་ན། དེར་ཐལ། འགྲེལ་ཆེན་ལས།",
      "head": "བྱང་ཆུབ་ཀྱི་སེམས་དང་",
      "tail": "བཞིན་ཞེས་གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "ཁྱབ་སྟེ། འཇུག་འགྲེལ་ལས།",
      "head": "དེ་ལ་ཕ་རོལ་ཞེས་བྱ་བ་",
      "tail": "དེ་བཞིན་ནོ་ཞེས་གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "བརྒྱད་སྟོང་དོན་བསྡུའི་འགྲེལ་པར། སློབ་དཔོན་གྱིས།",
      "head": "ཤེས་རབ་ཀྱི་ཕ་རོལ་ཏུ་",
      "tail": "གཞུང་དང་ལམ་གྱི་རང་བཞིན་ནོ་"
    },
    {
      "label": "QUOTE",
      "frame": "འཇུག་འགྲེལ་གྱི་ལུང་དེ་ཉིད་ཀྱི་ཕྱིར། གསུམ་ཆར་ཁས་བླངས་སོ། །ཡང་ལུང་དེ་ཉིད་ཀྱིས་སྦྱིན་པའི་ཕར་ཕྱིན་དང་ཤེར་ཕྱིན་གཉིས་རབ་ཀྱི་མཐར་ཕྱིན་པ་ཡིན་མིན་མཚུངས་པར་བསྟན་པ་མིན་པར་ཐལ། འཇུག་འགྲེལ་གྱི་ལུང་དེ་ཉིད་ཀྱི་བར་ཏུ་ཤེས་རབ་གཟུང་ནས་བྱེ་བྲག་ཏུ་བཤད་པ་ཡིན་ཏེ།",
      "head": "སྦྱིན་པ་ལ་སོགས་པ་རྣམས་",
      "tail": "ཕ་རོལ་ཏུ་ཕྱིན་པའོ་ཞེས་གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "ཁྱབ་པ་ཁས། འདོད་ན། རྣམ་འགྲེལ་ལས།",
      "head": "ཇི་ལྟར་གྲགས་ལས་གྲུབ་གང་ཡིན། །",
      "tail": "གང་ལ་དེ་སྐད་བརྗོད་ཕལ་པ། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཕལ་པ་ནི་གཞུང་དང་ལམ་གྱི་རང་བཞིན་ནོ་ཞེས་གསུངས་པའི་ཕྱིར་ཟེར་ན། གཞུང་ཤེར་ཕྱིན་དེ་ཡང་དེར་ཐལ།",
      "head": "ལུང་དེ་ཉིད་ཀྱི་ཕྱིར།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "འདོད་ན། འགྲེལ་ཆེན་ལས།",
      "head": "མཐོང་བ་ལ་སོགས་པའི་ལམ་",
      "tail": "ས་དང་པོ་ནས་བཤད་པ་དང་འགལ་ལོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཐེག་དམན་ལ་ཤེར་ཕྱིན་ཡོད་པ་ཡང་མི་འཐད་པར་ཐལ། བཤད་སྦྱར་ལས།",
      "head": "བསེ་རུ་ལྟ་བུ་རྣམས་ལ་ནི། །",
      "tail": "དྲུག་གི་སྤྱི་ལ་བཞུགས་པ་ལགས། །"
    },
    {
      "label": "QUOTE",
      "frame": "དེར་ཕར་ཕྱིན་དང་པོ་ལྔ་སངས་རྒྱས་의 སར་ཁྲིད་པར་བྱེད་པའི་ལམ་ཡོད་པའི་ཕྱིར་ཏེ།",
      "head": "སྦྱིན་དང་ཚུལ་ཁྲིམས་བཟོད་",
      "tail": "རབ་རྫོགས་པས། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་དང་། དབུས་མཐར།",
      "head": "ཁྱད་པར་ཅན་དང་ཁྱད་མེད་",
      "tail": "ས་བཅུ་དག་ཏུ་ཤེས་པར་བྱ། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་དང་།",
      "head": "དེ་དག་སོ་སོར་སྦྱིན་ལ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་དང་། སྡུད་པ་ལས།",
      "head": "ཤེས་རབ་མེད་ན་མིག་མེད་",
      "tail": "འདི་ཡི་མིང་འཐོབ་བོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྟེ། འགྲེལ་ཆེན་ལས།",
      "head": "སངས་རྒྱས་བཅོམ་ལྡན་འདས་",
      "tail": "ཞེས་བྱ་བ་ནི་བཏགས་པའོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "དེ་ཡང་སློབ་དཔོན་ཕྱོགས་ཀྱི་གླང་པོའི་ཞལ་སྔ་ནས།",
      "head": "ཤེས་རབ་ཕ་རོལ་ཕྱིན་གཉིས་",
      "tail": "གཞུང་ལམ་དག་ལས་དེ་སྒྲ་ཡིན། །"
    },
    {
      "label": "QUOTE",
      "frame": "ངེས་པར་གཟུང་བ་སྟེ། གཙོ་བོ་ལས་དབང་དུ་བྱས་པའོ། །དེ་རྣམས་ཉིད་ཀྱིས་ནི་མིན་ཏེ།",
      "head": "འདི་མེད་ན་མི་འབྱུང་བས་",
      "tail": "གསུངས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་སྟེ། ཡང་ཐེག་ཆེན་མཐོང་ལམ་པའི་རྒྱུད་ལ་རྣམ་མཁྱེན་ཡོད་པར་ཐལ། ཐེག་ཆེན་མཐོང་ལམ་པ་དེས་རང་རྣམ་མཁྱེན་ལ་གནས་ནས་གདུལ་བྱ་གཞན་དེ་ལ་དགོད་པར་མཛད་པའི་ཕྱིར་ཏེ། ཐེག་ཆེན་མཐོང་ལམ་གྱི་རྣམ་པ་འཆད་པའི་སྐབས་སུ།",
      "head": "རྣམ་ཀུན་མཁྱེན་པའི་ཚུལ་ལ་",
      "tail": "འགོད་དང་།"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་ཟེར་ན། རིམ་བཞིན་ཐེག་ཆེན་གྱི་མཐོང་ལམ་ཆོས་ཅན། འཁྲུལ་ཤེས་སུ་ཐལ། འཁྲུལ་པ་རང་བཞིན་མེད་པར་མངོན་སུམ་རྟོགས་པའི་ཤེས་པ་ཡིན་པའི་ཕྱིར། ཐེག་ཆེན་སྦྱོར་ལམ་གྱི་གནས་སྐབས་ན་སྒྲིབ་པའི་བག་ལ་ཉལ་མ་ལུས་པར་འཇོམས་པ་ཡོད་པར་ཐལ།",
      "head": "སྦྱོར་ལམ་པ་ཕྱིར་མི་ལྡོག་",
      "tail": "ཞེས་པའི་ཕྱིར།"
    },
    {
      "label": "QUOTE",
      "frame": "ཁྱབ་སྟེ། སློབ་དཔོན་གྱི་འགྲེལ་ཆེན་ལས།",
      "head": "ཐབས་བྱུང་དེ་རྒྱུ་ལྐོག་",
      "tail": "ཞེས་པའི་ལུང་ཁུངས་སུ་མཛད་"
    },
    {
      "label": "QUOTE",
      "frame": "ཞེས་དང་། ཉན་ཐོས་ལ་སོགས་མཐོང་བའི་ལམ། །ཞེས་དང་། མདོ་ལས་ཀྱང་།",
      "head": "ཐམས་ཅད་ཤེས་པ་ཉིད་ནི་",
      "tail": "གསུངས་པའི་ཕྱིར།"
    }
  ]
}
